export function getTemplatesBySpecialty(specialty: string): SpecialtyClinicalTemplate[] {
  return MASTER_SPECIALTY_TEMPLATES_REGISTRY.filter(t => t.specialtyName.toLowerCase().includes(specialty.toLowerCase()));
}
